<script setup lang="ts">
import { useI18n } from './i18n'
const { t, tm } = useI18n()
import {computed,nextTick,onBeforeUnmount,ref} from 'vue'
import {resolvedFont,textFontCSS} from './content-raster'
const props=defineProps<{value:string;fonts?:string[];disabled?:boolean}>()
const emit=defineEmits<{select:[font:string]}>()
const host=ref<HTMLElement>(),popup=ref<HTMLElement>(),search=ref(''),open=ref(false),position=ref({left:'0px',top:'0px'}),query=ref<HTMLInputElement>()
const choices=computed(()=>[...new Set(props.fonts?.length?props.fonts:['Arial','Helvetica','Times New Roman','Courier New'])].filter(font=>font.toLowerCase().includes(search.value.toLowerCase())).slice(0,300))
function close():void {open.value=false;document.removeEventListener('pointerdown',outside,true);window.removeEventListener('resize',close)}
function outside(event:PointerEvent):void {const target=event.target as Node;if(!host.value?.contains(target)&&!popup.value?.contains(target))close()}
async function toggle():Promise<void>{if(open.value){close();return}if(props.disabled)return;const bounds=host.value!.getBoundingClientRect();position.value={left:`${Math.max(8,Math.min(bounds.left,window.innerWidth-328))}px`,top:`${Math.max(8,Math.min(bounds.bottom+4,window.innerHeight-280))}px`};search.value='';open.value=true;document.addEventListener('pointerdown',outside,true);window.addEventListener('resize',close);await nextTick();query.value?.focus()}
function choose(font:string):void {emit('select',font);close()}
onBeforeUnmount(close)
</script>
<template><span ref="host" class="font-picker"><input :value="value" :aria-label="t('Font family')" maxlength="200" list="content-installed-fonts" :disabled="disabled" @change="emit('select',($event.target as HTMLInputElement).value)"><datalist id="content-installed-fonts"><option v-for="font in fonts" :key="font" :value="font"/></datalist><button type="button" :aria-label="t('Browse font previews')" :aria-expanded="open" :disabled="disabled" @click="toggle">▾</button><Teleport to="body"><div v-if="open" ref="popup" class="font-popup" :style="position" role="dialog" :aria-label="t('Installed font previews')" @keydown.escape.stop.prevent="close"><input ref="query" v-model="search" :aria-label="t('Search fonts')" :placeholder="t('Search fonts')"><div class="font-choices" role="listbox" :aria-label="t('Choose font')"><button v-for="font in choices" :key="font" type="button" role="option" :aria-selected="value===font" :aria-label="t('Use font {font}', {font})" @click="choose(font)"><span>{{font}}</span><span class="font-sample" :style="{fontFamily:textFontCSS(font),fontWeight:resolvedFont(font).weight,fontStyle:resolvedFont(font).fontStyle}">Aa Bb · 文字 0123</span></button><p v-if="!choices.length">{{ t('No matching installed fonts.') }}</p></div></div></Teleport></span></template>
<style scoped>
.font-picker{display:flex;gap:2px;align-items:center;min-width:0}.font-picker input{min-width:0;width:160px;font:inherit;color:inherit;background:#1b1b1b;border:1px solid #474747;border-radius:4px;padding:5px}.font-picker button{flex:none;width:24px;padding:4px;color:inherit;background:#303030;border:1px solid #474747;border-radius:4px;cursor:pointer}.font-popup{position:fixed;z-index:1000;width:320px;box-sizing:border-box;padding:8px;background:#252525;border:1px solid #555;border-radius:7px;box-shadow:0 8px 24px #000b;color:#ddd;font:12px system-ui}.font-popup>input{box-sizing:border-box;width:100%;padding:7px;background:#181818;color:inherit;border:1px solid #555;border-radius:4px}.font-choices{max-height:224px;overflow:auto;margin-top:5px}.font-choices button{display:flex;flex-direction:column;width:100%;padding:7px;text-align:left;border:0;border-radius:4px;color:inherit;background:transparent;cursor:pointer}.font-choices button:hover,.font-choices button[aria-selected=true]{background:#345e88}.font-sample{font-size:19px;margin-top:4px}
</style>
